// Shock (ch/shock.js): the measurements on the views cut from the heart mesh, and the tables of
// what they measure along the chapter's tracks, on each heart. Each measurement takes an EchoView
// after frame() and works in plane cm, as meshjet.js does. The page prints the tables' values,
// and its calipers draw these same measurements on the image.
import * as THREE from '../vendor/three.bundle.min.js';
import { ABD } from './abdomen.js';
import { hingesOf, onPlane, blood, cavity, middle, sub, add, mul, dot, len, unit, perp } from './meshjet.js';
import { annulusCaliper } from './aortacal.js';
import { annulusOf } from './gl/prostheticmesh.js';

/** The chord of polygon P through Q along unit direction t: its two ends, or null. */
function chord(P, Q, t) {
  const n = perp(t);
  let lo = Infinity, hi = -Infinity;
  for (let i = 0, j = P.length - 1; i < P.length; j = i++) {
    const a = P[j], b = P[i], da = dot(sub(a, Q), n), db = dot(sub(b, Q), n);
    if ((da > 0) === (db > 0)) continue;
    const X = add(a, mul(sub(b, a), da / (da - db))), u = dot(sub(X, Q), t);
    lo = Math.min(lo, u); hi = Math.max(hi, u);
  }
  return Number.isFinite(lo) && hi > lo ? [add(Q, mul(t, lo)), add(Q, mul(t, hi))] : null;
}

/**
 * A ventricle's basal diameter on the four-chamber view at systolic weight s, as Lang 2015 and
 * Mukherjee 2025 take it: the widest the cavity is in its basal third, parallel to the annulus.
 * valve: 'MitralValve' (LV) or 'TricuspidValve' (RV). The cavity is closed at the annulus, the
 * line between the valve's hinge points. Returns { d (cm), ends: [a, b] } or null.
 */
export function basalDiameter(ev, valve, s = 0) {
  const h = hingesOf(ev, valve);
  if (!h) return null;
  const M = middle(h), t = unit(sub(h[1], h[0])), apex = onPlane(ev, ev.anchors(s).apex);
  let n = perp(t);
  if (dot(sub(apex, M), n) < 0) n = mul(n, -1);
  const P = cavity(ev, blood(ev, add(M, mul(n, 2.5))), [h]);
  if (P.length < 24) return null;
  // the chamber's length from the annulus line, and its widest chord in the basal third
  const L = Math.max(...P.map((p) => dot(sub(p, M), n)));
  let best = null;
  for (let k = 1; k <= 24; k++) {
    const c = chord(P, add(M, mul(n, (k / 24) * (L / 3))), t);
    if (c && (!best || len(sub(c[1], c[0])) > best.d)) best = { d: len(sub(c[1], c[0])), ends: c };
  }
  return best;
}

// the pericardium's bright line straddles its section (echo.js periW): the echo-free space ends
// at its inner edge
const PERI_HALF = 0.075;
/** The point of segment a-b nearest p. */
function onSeg(p, a, b) {
  const e = sub(b, a), l2 = dot(e, e) || 1e-12;
  return add(a, mul(e, Math.max(0, Math.min(1, dot(sub(p, a), e) / l2))));
}
/**
 * The pericardial effusion on the short axis at the papillary muscles at systolic weight s: the
 * largest echo-free space over the LV's free wall, from the epicardium to the inner edge of the
 * pericardium's line, square to the wall. Rays from the LV's centre, within 75° either side of
 * the line from the RV's anchor through the LV's centre, find the wall's outer edge: the last
 * crossing out of the myocardium before the sac. From there the space runs to the nearest point
 * of the sac. Fat in the grooves lies off these rays. The largest of the medians of five
 * neighbouring rays is the effusion, so one ray that grazes a wall does not set it. Returns
 * { d (cm), ends: [epicardium, pericardium] }, or null when the rays meet no sac.
 */
export function effusionGap(ev, s = 0) {
  const last = ev.last;
  if (!last || !last.peri || !last.peri.length) return null;
  const an = ev.anchors(s), C = blood(ev, onPlane(ev, an.lv)), away = unit(sub(C, onPlane(ev, an.rv)));
  const tissue = last.tissue.filter((L) => L.closed), peri = last.peri;
  const segs = [];
  for (const L of peri) for (let i = 0; i < L.pts.length - (L.closed ? 0 : 1); i++) segs.push([L.pts[i], L.pts[(i + 1) % L.pts.length]]);
  const rays = [];
  for (let a = -75; a <= 75; a += 2.5) {
    const r = (a * Math.PI) / 180, dir = [away[0] * Math.cos(r) - away[1] * Math.sin(r), away[0] * Math.sin(r) + away[1] * Math.cos(r)];
    const walls = ev.intervals(tissue, C, dir, 14);
    // the sac's first crossing outside every wall, and the last wall that ends before it
    const p = ev.crossings(peri, C, dir, 14).find((x) => !walls.some(([a0, a1]) => x > a0 && x < a1));
    const w = p === undefined ? null : walls.filter(([, a1]) => a1 < p).pop();
    if (!w) { rays.push(null); continue; }
    const E = add(C, mul(dir, w[1]));
    let Q = null, d = Infinity;
    for (const [a0, b0] of segs) { const q = onSeg(E, a0, b0), e = len(sub(q, E)); if (e < d) { d = e; Q = q; } }
    rays.push(Q ? { d: d - PERI_HALF, ends: [E, add(E, mul(unit(sub(Q, E)), d - PERI_HALF))] } : null);
  }
  let best = null;
  for (let i = 2; i < rays.length - 2; i++) {
    const win = rays.slice(i - 2, i + 3);
    if (win.some((x) => !x)) continue;
    const med = win.map((x) => x.d).sort((x, y) => x - y)[2];
    if (!best || med > best.med) best = { med, ray: win.find((x) => x.d === med) };
  }
  return best ? { d: best.ray.d, ends: best.ray.ends } : null;
}

// The IVC's measuring site: 2.0 cm along the IVC from the end of the model's IVC at the RA,
// past the hepatic vein's mouth (about 1.3 cm along), within the 0.5-3.0 cm of Mukherjee 2025
export const IVC_SITE = 2.0;
let ivcPath = null;
/** The IVC's centre line (world cm) as points with their distance along it, from the RA end. */
function ivcLine() {
  if (!ivcPath) {
    const curve = new THREE.CatmullRomCurve3(ABD.ivc.pts.map((p) => new THREE.Vector3(...p)));
    const n = 200, pts = curve.getSpacedPoints(n), L = curve.getLength();
    ivcPath = pts.map((p, i) => ({ p, at: (i / n) * L }));
  }
  return ivcPath;
}
/**
 * The IVC's measuring site on the plane: S, the site's point, and t, the vessel's course there,
 * pointing away from the RA. Null when the plane shows no IVC.
 */
export function ivcAxis(ev) {
  if (!ev.abd || !ev.abd.ivc || !ev.g) return null;
  const path = ivcLine();
  const i = path.findIndex((q) => q.at >= IVC_SITE), A = path[Math.max(0, i - 3)].p, B = path[Math.min(path.length - 1, i + 3)].p;
  return { S: onPlane(ev, path[i].p), t: unit(sub(onPlane(ev, B), onPlane(ev, A))) };
}
/**
 * The IVC's diameter at its measuring site on the subcostal IVC view: the lumen square to the
 * vessel's course on the plane, wall to wall, through the site's point on the plane. Returns
 * { d (cm), ends: [a, b], site } or null.
 */
export function ivcDiameter(ev) {
  const X = ivcAxis(ev);
  if (!X) return null;
  const { S, t } = X, n = perp(t);
  const loops = ev.abd.ivc.section(ev.g).filter((L) => L.closed);
  const hits = ev.crossings(loops, add(S, mul(n, -4)), n, 8).map((x) => x - 4);
  const below = hits.filter((x) => x < 0), above = hits.filter((x) => x > 0);
  if (!below.length || !above.length) return null;
  const lo = below[below.length - 1], hi = above[0];
  return { d: hi - lo, ends: [add(S, mul(n, lo)), add(S, mul(n, hi))], site: S };
}

// The LVOT: its diameter in midsystole on the parasternal long axis, inner edge to inner edge,
// square to the root's axis, LVOT_AT cm below the annulus (aortacal.js annulusCaliper), at the
// level of the PW sample just below the valve (pressure.js)
export const LVOT_AT = 0.5;
/**
 * The LVOT diameter at systolic weight s: from the septum's inner edge to the anterior mitral
 * leaflet's, on the line square to the root's axis LVOT_AT cm toward the apex from the middle of
 * the annulus caliper. Where the plane shows no leaflet that far down (the Barlow heart's
 * leaflets billow away from it), the line moves up toward the annulus in 0.05 cm steps until it
 * meets a wall on both sides within 1.25 times the annulus. Returns { d (cm), ends: [septum,
 * leaflet], at: cm below the annulus, ann: the annulus caliper } or null.
 */
export function lvotDiameter(ev, s) {
  const A = annulusCaliper(ev, s, annulusOf);
  if (!A) return null;
  const r = ev.anat.aorticRoot, g = ev.g, n = unit(sub(A.ii1, A.ii0));
  // the root's axis points into the aorta; the LVOT lies the other way
  const ax = unit([r.dot(g.r), r.dot(g.d)]), M = middle([A.ii0, A.ii1]);
  const loops = [...ev.last.tissue.filter((L) => L.closed && L.pts.length > 2), ...ev.last.valves.filter((V) => V.valve === 'MitralValve' && V.pts.length > 1)];
  for (let k = 0; k <= 10; k++) {
    const at = LVOT_AT * (1 - k / 10), C = add(M, mul(ax, -at));
    const hits = ev.crossings(loops, add(C, mul(n, -4)), n, 8).map((x) => x - 4);
    const before = hits.filter((x) => x < 0), after = hits.filter((x) => x > 0);
    if (!before.length || !after.length) continue;
    const lo = before[before.length - 1], hi = after[0];
    if (hi - lo <= 1.25 * A.ii) return { d: hi - lo, ends: [add(C, mul(n, lo)), add(C, mul(n, hi))], at, ann: A };
  }
  return null;
}

