/** The image's measurements on heart for case k at slider position s, between the table's nodes. */
export function measuredAt(heart, k, s) {
  const T = (TABLES[heart] || TABLES.normal || {})[k];
  if (!T) return null;
  const x = Math.min(NODES, Math.max(0, s * NODES)), i = Math.min(NODES - 1, Math.floor(x)), u = x - i;
  const out = {};
  for (const [key, col] of Object.entries(T)) out[key] = col[i] + (col[i + 1] - col[i]) * u;
  return out;
}
